```js
// Boot and wiring for the Leonida Trophy Ledger.
//
// Loads app/data/trophies.json, renders the checklist, the detail pane, the
// roadmap and the missables page, and wires every control: search, kind and
// grade filters, the spoiler setting, export, import and reset. Progress
// lives in localStorage through store.js and never leaves the browser.
//
// Preview parameters, for screenshots and for sharing a view: ?view=roadmap
// | missables | about | tracker, ?open=<trophy id> to open a trophy's guide,
// ?spoilers=on to start with story spoilers hidden, and ?seed=<n> to preview
// the tracker with the first n trophies marked earned (preview only — the
// seed is not saved).

import { loadEarned, saveEarned, toggleEarned, exportEarned, importEarnedFile, resetEarned, countByGrade } from './store.js';
import { applyFilters, isSpoilerHidden } from './filters.js';
import { trophyRowHtml, detailHtml, roadmapHtml, missablesHtml, sourceListHtml, progressText } from './views.js';

const listEl = document.getElementById('trophyList');
const detailEl = document.getElementById('detailPane');
const listMetaEl = document.getElementById('listMeta');
const emptyNoteEl = document.getElementById('emptyNote');
const searchEl = document.getElementById('searchInput');
const gradeEl = document.getElementById('gradeFilter');
const earnedEl = document.getElementById('earnedFilter');
const kindWrapEl = document.getElementById('kindFilters');
const spoilerEl = document.getElementById('spoilerToggle');

let trophies = [];
let earned = loadEarned();
let selectedId = null;
let spoilersOn = false;
const filters = { kind: 'all', grade: 'all', earnedMode: 'all', query: '' };

async function boot() {
  const response = await fetch('data/trophies.json');
  const data = await response.json();
  trophies = Array.isArray(data) ? data : data.trophies;

  readPreviewParams();
  renderRoadmap();
  renderMissables();
  renderSources();
  renderAll();
  wireEvents();
}

// The preview parameters from the address bar. ?seed marks the first n
// trophies earned for this view only and is never written to storage.
function readPreviewParams() {
  const params = new URLSearchParams(location.search);
  const view = params.get('view');
  if (view) showView(view);
  if (params.get('spoilers') === 'on') {
    spoilersOn = true;
    spoilerEl.checked = true;
  }
  const openId = Number.parseInt(params.get('open') || '', 10);
  if (Number.isInteger(openId) && trophies.some((t) => t.id === openId)) {
    selectedId = openId;
  }
  const seed = Number.parseInt(params.get('seed') || '', 10);
  if (Number.isInteger(seed) && seed > 0) {
    for (const trophy of trophies.slice(0, seed)) earned.add(trophy.id);
  }
  if (!selectedId && trophies.length > 0) selectedId = trophies[0].id;
}

function renderAll() {
  renderProgress();
  renderList();
  renderDetail();
}

function renderProgress() {
  const counts = countByGrade(trophies, earned);
  const { done, total, pct, parts } = progressText(trophies, earned, counts);
  document.getElementById('earnedCount').textContent = String(done);
  document.getElementById('earnedPct').textContent = `${pct}%`;
  document.getElementById('progressFill').style.width = `${pct}%`;
  document.getElementById('gradeBreakdown').textContent =
    `${parts} — ${total} trophies: 1 platinum, 2 gold, 6 silver, 46 bronze.`;
}

function renderList() {
  const visible = applyFilters(trophies, earned, filters);
  listEl.innerHTML = visible
    .map((trophy) => trophyRowHtml(trophy, earned, spoilersOn, selectedId))
    .join('');
  const shown = visible.length;
  const total = trophies.length;
  listMetaEl.textContent =
    shown === total
      ? `Showing all ${total} trophies.`
      : `Showing ${shown} of ${total} trophies.`;
  emptyNoteEl.hidden = shown !== 0;
}

function renderDetail() {
  const trophy = trophies.find((item) => item.id === selectedId) || null;
  detailEl.innerHTML = detailHtml(trophy, earned, spoilersOn);
}

function renderRoadmap() {
  document.getElementById('roadmapSteps').innerHTML = roadmapHtml();
}

function renderMissables() {
  document.getElementById('missableList').innerHTML = missablesHtml(trophies);
}

function renderSources() {
  document.getElementById('sourceList').innerHTML = sourceListHtml();
}

function showView(name) {
  const known = ['tracker', 'roadmap', 'missables', 'about'];
  const view = known.includes(name) ? name : 'tracker';
  for (const item of known) {
    document.getElementById(`view${cap(item)}`).classList.toggle('is-visible', item === view);
    document.getElementById(`tab${cap(item)}`).classList.toggle('is-active', item === view);
  }
}

function cap(word) {
  return word.charAt(0).toUpperCase() + word.slice(1);
}

function wireEvents() {
  document.querySelectorAll('.tab').forEach((tab) => {
    tab.addEventListener('click', () => showView(tab.dataset.view));
  });

  searchEl.addEventListener('input', () => {
    filters.query = searchEl.value;
    renderList();
  });
  gradeEl.addEventListener('change', () => {
    filters.grade = gradeEl.value;
    renderList();
  });
  earnedEl.addEventListener('change', () => {
    filters.earnedMode = earnedEl.value;
    renderList();
  });
  kindWrapEl.addEventListener('click', (event) => {
    const button = event.target.closest('[data-kind]');
    if (!button) return;
    filters.kind = button.dataset.kind;
    kindWrapEl.querySelectorAll('.kind').forEach((item) => {
      item.classList.toggle('is-active', item === button);
    });
    renderList();
  });

  spoilerEl.addEventListener('change', () => {
    spoilersOn = spoilerEl.checked;
    renderList();
    renderDetail();
  });

  // Clicking a row selects it; clicking its checkbox toggles earned. The
  // checkbox stop is what keeps one click from doing both.
  listEl.addEventListener('click', (event) => {
    const row = event.target.closest('.trophy-row');
    if (!row) return;
    const id = Number.parseInt(row.dataset.id, 10);
    if (event.target.classList.contains('trophy-check')) {
      toggleEarned(earned, id);
      renderAll();
      return;
    }
    selectedId = id;
    renderList();
    renderDetail();
  });
  listEl.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    const row = event.target.closest('.trophy-row');
    if (!row) return;
    event.preventDefault();
    selectedId = Number.parseInt(row.dataset.id, 10);
    renderList();
    renderDetail();
  });

  detailEl.addEventListener('click', (event) => {
    const button = event.target.closest('[data-earn]');
    if (!button) return;
    const id = Number.parseInt(button.dataset.earn, 10);
    toggleEarned(earned, id);
    renderAll();
  });

  document.getElementById('exportBtn').addEventListener('click', () => {
    exportEarned(earned, trophies.length);
  });

  document.getElementById('importInput').addEventListener('change', async (event) => {
    const file = event.target.files && event.target.files[0];
    if (!file) return;
    try {
      const imported = await importEarnedFile(file);
      if (!imported) {
        alert('That file does not look like a trophy progress export.');
        return;
      }
      earned = new Set([...imported].filter((id) => trophies.some((t) => t.id === id)));
      saveEarned(earned);
      renderAll();
    } catch {
      alert('Could not read that file. It needs to be a JSON progress export from this guide.');
    }
    event.target.value = '';
  });

  document.getElementById('resetBtn').addEventListener('click', () => {
    if (!confirm('Clear all earned trophies? This cannot be undone. Export first if you want a backup.')) return;
    earned = resetEarned();
    renderAll();
  });
}

boot();
```

### app/store.js (2973 bytes)

```js
// Progress store: one earned-set, kept in localStorage, exportable to a file
// and importable back. Nothing leaves the browser; there is no account and
// no network call anywhere in this module.

export const STORAGE_KEY = 'leonida-trophy-ledger-v1';

// Read the saved earned ids. A damaged or foreign value is treated as empty
// rather than crashing the page.
export function loadEarned() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return new Set();
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return new Set();
    return new Set(parsed.filter((id) => Number.isInteger(id)));
  } catch {
    return new Set();
  }
}

// Persist the earned ids as a sorted JSON array.
export function saveEarned(earned) {
  const ids = [...earned].filter((id) => Number.isInteger(id)).sort((a, b) => a - b);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(ids));
}

// Flip one trophy and persist. Returns the new earned state of that trophy.
export function toggleEarned(earned, id) {
  if (earned.has(id)) earned.delete(id);
  else earned.add(id);
  saveEarned(earned);
  return earned.has(id);
}

// Download the progress as a JSON file the reader can keep or move to
// another browser. The filename carries the date so several exports do not
// overwrite each other silently.
export function exportEarned(earned, total) {
  const payload = {
    app: 'Leonida Trophy Ledger',
    game: 'Grand Theft Auto VI',
    exportedAt: new Date().toISOString(),
    earned: [...earned].sort((a, b) => a - b),
    total,
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  const stamp = new Date().toISOString().slice(0, 10);
  link.href = url;
  link.download = `gta6-trophies-${stamp}.json`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

// Read an exported file back into an earned set. Only ids that are integers
// are kept; anything else in the file is ignored. Returns null when the file
// is not a progress export we recognise.
export async function importEarnedFile(file) {
  const text = await file.text();
  const parsed = JSON.parse(text);
  const ids = Array.isArray(parsed) ? parsed : parsed.earned;
  if (!Array.isArray(ids)) return null;
  return new Set(ids.filter((id) => Number.isInteger(id)));
}

// Wipe all saved progress after a confirm in the caller.
export function resetEarned() {
  localStorage.removeItem(STORAGE_KEY);
  return new Set();
}

// Count earned trophies per grade, for the header breakdown line.
export function countByGrade(trophies, earned) {
  const counts = {};
  for (const trophy of trophies) {
    const grade = trophy.grade;
    counts[grade] = counts[grade] || { earned: 0, total: 0 };
    counts[grade].total += 1;
    if (earned.has(trophy.id)) counts[grade].earned += 1;
  }
  return counts;
}
```

### app/filters.js (3083 bytes)

```js
// Filtering and the spoiler rule: which trophies a view shows, and what a
// spoiler-hidden trophy looks like until it is earned.

// A trophy matches the kind filter when its kind list holds the kind, or
// when the missable filter is on and the trophy is flagged missable. The
// platinum has no kind of its own; it shows under All and under Activities.
export function matchesKind(trophy, kind) {
  if (kind === 'all') return true;
  if (kind === 'missable') return trophy.missable === true;
  if (kind === 'online') return trophy.kind === 'online';
  return Array.isArray(trophy.kinds) && trophy.kinds.includes(kind);
}

export function matchesGrade(trophy, grade) {
  return grade === 'all' || trophy.grade === grade;
}

export function matchesEarned(trophy, earned, mode) {
  if (mode === 'earned') return earned.has(trophy.id);
  if (mode === 'todo') return !earned.has(trophy.id);
  return true;
}

// Search across the name, the official description and the guide text, so a
// search for a mission, a place or an activity finds the trophy behind it.
export function matchesSearch(trophy, query) {
  const needle = query.trim().toLowerCase();
  if (!needle) return true;
  const haystack = [trophy.name, trophy.description, trophy.guide, trophy.note || '']
    .join(' ')
    .toLowerCase();
  return needle.split(/\s+/).every((word) => haystack.includes(word));
}

// Apply every active filter at once and return the visible trophies in
// list order.
export function applyFilters(trophies, earned, filters) {
  return trophies.filter(
    (trophy) =>
      matchesKind(trophy, filters.kind) &&
      matchesGrade(trophy, filters.grade) &&
      matchesEarned(trophy, earned, filters.earnedMode) &&
      matchesSearch(trophy, filters.query),
  );
}

// Spoiler rule: when spoilers are on, a story trophy that is not earned yet
// shows a placeholder name and description instead of the real ones. The
// platinum and the gold for the final mission are story-adjacent too, so
// they hide the same way. Everything else is always shown.
const SPOILER_KINDS = ['story'];

export function isSpoilerHidden(trophy, spoilersOn, earned) {
  if (!spoilersOn) return false;
  if (earned.has(trophy.id)) return false;
  return (
    Array.isArray(trophy.kinds) &&
    trophy.kinds.some((kind) => SPOILER_KINDS.includes(kind))
  );
}

// What a hidden trophy displays in the list and the detail pane.
export function spoilerMask(trophy) {
  return {
    name: 'Hidden story trophy',
    description: 'Earn this trophy to reveal its name and description.',
  };
}

// Count how many trophies of each kind the list holds, for the filter
// buttons' context. Missable counts the flagged ones; online counts none.
export function countByKind(trophies) {
  const counts = { story: 0, missable: 0, collectibles: 0, activities: 0, online: 0 };
  for (const trophy of trophies) {
    if (trophy.missable) counts.missable += 1;
    if (Array.isArray(trophy.kinds)) {
      for (const kind of trophy.kinds) {
        if (kind in counts) counts[kind] += 1;
      }
    }
  }
  return counts;
}
```

### app/views.js (8340 bytes)

```js
// Views: everything the reader sees — the checklist rows, the detail pane
// with a trophy's guide and its sources, the roadmap steps, the missables
// page and the source directory. All markup is built from the trophy data;
// no HTML is fetched or pasted in from anywhere else.

import { SOURCES, ROADMAP_STAGES, KIND_LABELS } from './sources.js';
import { isSpoilerHidden, spoilerMask } from './filters.js';

// Escape text that came from data before it goes into HTML, so a stray
// character in a trophy name can never break the page.
export function escapeHtml(text) {
  return String(text)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

export function gradeLabel(grade) {
  return grade.charAt(0).toUpperCase() + grade.slice(1);
}

// One checklist row: checkbox, medal dot, name, official description and
// tags for kind, missable and hidden. A spoiler-hidden trophy shows the
// mask instead of its real name and description.
export function trophyRowHtml(trophy, earned, spoilersOn, selectedId) {
  const hidden = isSpoilerHidden(trophy, spoilersOn, earned);
  const shown = hidden ? spoilerMask(trophy) : trophy;
  const isEarned = earned.has(trophy.id);
  const classes = ['trophy-row'];
  if (isEarned) classes.push('is-earned');
  if (trophy.id === selectedId) classes.push('is-selected');

  const tags = [];
  if (trophy.missable) tags.push('<span class="tag missable">Missable</span>');
  if (Array.isArray(trophy.kinds)) {
    for (const kind of trophy.kinds) {
      const label = KIND_LABELS[kind];
      if (label) tags.push(`<span class="tag ${kind === 'story' ? 'story' : kind === 'collectibles' ? 'collect' : ''}">${escapeHtml(label)}</span>`);
    }
  }
  if (trophy.hidden) tags.push('<span class="tag">Hidden on PSN</span>');

  return `<li class="${classes.join(' ')}" data-id="${trophy.id}" tabindex="0" role="button"
      aria-pressed="${isEarned}" aria-label="${escapeHtml(shown.name)}">
    <input type="checkbox" class="trophy-check" data-id="${trophy.id}"
      ${isEarned ? 'checked' : ''} aria-label="Mark ${escapeHtml(shown.name)} as earned">
    <span class="medal ${escapeHtml(trophy.grade)}" title="${escapeHtml(gradeLabel(trophy.grade))}"></span>
    <span>
      <span class="trophy-name">${escapeHtml(shown.name)}${trophy.hidden ? ' <span class="hidden-mark">(hidden)</span>' : ''}</span>
      <span class="trophy-desc">${escapeHtml(shown.description)}</span>
      <span class="trophy-tags">${tags.join('')}</span>
    </span>
    <span class="grade-label">${escapeHtml(gradeLabel(trophy.grade))}</span>
  </li>`;
}

// The detail pane: official name, description and grade, the guide in our
// own words, what it needs (count, stage, when it can be missed) and the
// sources the guide draws on, each named and linked where we have a link.
export function detailHtml(trophy, earned, spoilersOn) {
  if (!trophy) {
    return `<p class="detail-empty">Pick a trophy from the list to see its guide,
      its sources and when it can be missed. Tick the box to mark it earned.</p>`;
  }
  const hidden = isSpoilerHidden(trophy, spoilersOn, earned);
  const shown = hidden ? spoilerMask(trophy) : trophy;
  const isEarned = earned.has(trophy.id);

  const facts = [];
  if (trophy.count) facts.push(`<dt>Count</dt><dd>${escapeHtml(trophy.count)}</dd>`);
  if (trophy.stage) facts.push(`<dt>Roadmap step</dt><dd>Step ${trophy.stage} — ${escapeHtml(stageName(trophy.stage))}</dd>`);
  if (trophy.missable) {
    facts.push('<dt>Missable?</dt><dd><strong>Yes — possibly.</strong> See the Missables tab before you leave Chapter 1.</dd>');
  } else if (trophy.kinds && trophy.kinds.includes('story')) {
    facts.push('<dt>Missable?</dt><dd>No. Story trophies pop automatically and cannot be missed.</dd>');
  } else {
    facts.push('<dt>Missable?</dt><dd>No. It can still be earned in free roam after the story.</dd>');
  }

  const sourceItems = (trophy.sources || ['exophase', 'psnprofiles'])
    .map((key) => sourceLine(key))
    .join('');

  return `<h2>${escapeHtml(shown.name)}</h2>
    <p class="official"><strong>Official description:</strong> ${escapeHtml(shown.description)}<br>
    <strong>Grade:</strong> ${escapeHtml(gradeLabel(trophy.grade))}${trophy.hidden ? ' &middot; Hidden on PlayStation until earned' : ''}</p>
    <div class="sources-box">
      <h3>Sources for this guide</h3>
      <ul>${sourceItems}</ul>
      <p>Guide text is written in our own words for this guide. Sources are cited, never copied. Official names and descriptions are shown as PlayStation publishes them.</p>
    </div>
    <div class="detail-guide">${guideParagraphs(hidden ? null : trophy.guide)}</div>
    <dl class="detail-meta">${facts.join('')}</dl>
    <button type="button" class="earn-btn${isEarned ? ' earned' : ''}" data-earn="${trophy.id}">
      ${isEarned ? 'Earned — tap to unmark' : 'Mark as earned'}
    </button>`;
}

function stageName(stage) {
  return (
    {
      1: 'Story and optional missions',
      2: '100% Completion checklist',
      3: 'Strangers & Freaks and cleanup',
    }[stage] || 'Cleanup'
  );
}

// Split the guide text into paragraphs on blank lines; a hidden trophy's
// guide stays hidden with it.
function guideParagraphs(guide) {
  if (!guide) {
    return '<p>This story trophy is hidden until you earn it. Turn the spoiler setting off to read its guide.</p>';
  }
  return guide
    .split(/\n\s*\n/)
    .map((para) => `<p>${escapeHtml(para.trim())}</p>`)
    .join('');
}

// One source line: a link when we have a verified URL, plain text when we
// only have the name. Never invent a link.
function sourceLine(key) {
  const source = SOURCES[key];
  if (!source) return '';
  if (source.url) {
    return `<li><a href="${escapeHtml(source.url)}" target="_blank" rel="noopener">${escapeHtml(source.name)}</a></li>`;
  }
  return `<li>${escapeHtml(source.name)}</li>`;
}

// The roadmap view: the three steps with their points and the trophies
// each step clears.
export function roadmapHtml() {
  return ROADMAP_STAGES.map(
    (stage) => `<li>
      <h3>${escapeHtml(stage.title)}</h3>
      <p class="step-time">${escapeHtml(stage.time)}</p>
      <ul>${stage.points.map((point) => `<li>${escapeHtml(point)}</li>`).join('')}</ul>
      <p class="step-trophies"><strong>Clears:</strong> ${escapeHtml(stage.trophies)}</p>
    </li>`,
  ).join('');
}

// The missables view: the one possibly-missable trophy in full, with its
// warning, plus a note that nothing else is known to be missable.
export function missablesHtml(trophies) {
  const flagged = trophies.filter((trophy) => trophy.missable);
  if (flagged.length === 0) {
    return '<p>No trophy in this list is flagged missable.</p>';
  }
  return flagged
    .map(
      (trophy) => `<article class="missable-card">
        <h3>${escapeHtml(trophy.name)} — possibly missable</h3>
        <p class="official"><strong>Official description:</strong> ${escapeHtml(trophy.description)}</p>
        <div class="detail-guide">${guideParagraphs(trophy.guide)}</div>
        <p class="cite-line">Sources: ${trophy.sources.map((key) => escapeHtml(SOURCES[key]?.name || key)).join('; ')}.</p>
      </article>
      <p>Every other trophy can still be earned in free roam after the story, according to PowerPyx and Sixshore — no other missable is known at the time of writing.</p>`,
    )
    .join('');
}

// The source directory on the About tab: every source once, with its link
// where we have one.
export function sourceListHtml() {
  return Object.values(SOURCES)
    .map((source) =>
      source.url
        ? `<li><a href="${escapeHtml(source.url)}" target="_blank" rel="noopener">${escapeHtml(source.name)}</a></li>`
        : `<li>${escapeHtml(source.name)}</li>`,
    )
    .join('');
}

// Header progress: earned count, percentage and the per-grade breakdown.
export function progressText(trophies, earned, counts) {
  const total = trophies.length;
  const done = earned.size;
  const pct = total ? Math.round((done / total) * 100) : 0;
  const parts = ['platinum', 'gold', 'silver', 'bronze']
    .filter((grade) => counts[grade])
    .map((grade) => `${counts[grade].earned}/${counts[grade].total} ${grade}`)
    .join(' · ');
  return { done, total, pct, parts };
}
